export type CalculationFactorRow = {
  label: string;
  value: string;
};

export type CalculationFactorGroup = {
  title: string;
  rows: CalculationFactorRow[];
};

export type TransactionCalculationReadout = {
  headline: string;
  methodLabel: string;
  tierLabel: string;
  summary: string;
  steps: string[];
  groups: CalculationFactorGroup[];
};

type FactorLineage = {
  id?: string;
  factor?: number;
  unit?: string;
  source?: string;
  sourceVersion?: string;
  sourceDocument?: string;
  sourceUrl?: string;
  relativeUncertainty?: number;
  biogenic?: boolean;
  justification?: string;
  notes?: string;
  geography?: string;
  gwpBasis?: string;
  [key: string]: unknown;
};

export type CalculationFootprintInput = {
  co2Emissions?: number;
  screeningCo2Emissions?: number;
  emissionFactor?: number;
  quantificationMethod?: string;
  calculationMethod?: string;
  dataQualityTier?: string;
  dataSource?: string;
  reportingMode?: string;
  ghgScope3Category?: string;
  activityQuantity?: number;
  activityUnit?: string;
  exclusionReason?: string;
  biogenicCo2Kg?: number;
  carbonModelVersion?: string;
  carbonReportingLabel?: string;
  emissionBreakdown?: { scope1?: number; scope2?: number; scope3?: number };
  screeningEmissionBreakdown?: { scope1?: number; scope2?: number; scope3?: number };
  factorLineage?: FactorLineage | null;
  fuelContext?: Record<string, unknown> | null;
  feraSupplement?: {
    feraKg?: number;
    upstreamShare?: number;
    upstreamMethod?: string | null;
    energyType?: string | null;
    wttFactor?: number | null;
    wttUnit?: string | null;
    ghgScope3Category?: string;
  } | null;
  tdLossSupplement?: {
    tdLossKg?: number;
    lossRate?: number;
    application?: string;
    upstreamMethod?: string;
    rationale?: string;
  } | null;
  screeningFeraSupplement?: CalculationFootprintInput['feraSupplement'];
  screeningTdLossSupplement?: CalculationFootprintInput['tdLossSupplement'];
  scope2Reporting?: {
    locationBasedKg?: number;
    marketBasedKg?: number;
    method?: string;
  } | null;
  complianceFlags?: string[] | Record<string, boolean>;
  metrics?: {
    carbonIntensity?: number;
    emissionsPerThousandCurrency?: number;
    estimatedScope?: string;
    appliedFactors?: Record<string, unknown>;
    fuelContext?: Record<string, unknown> | null;
  } | null;
  taxableAmountMeta?: { amount?: number; gstStripped?: boolean; gstPercent?: number } | null;
};

export type CalculationContextInput = {
  amount?: number;
  currency?: string;
  category?: string;
  subcategory?: string;
  quantity?: number;
  unit?: string;
  description?: string;
  ownership?: string;
};

const METHOD_LABELS: Record<string, string> = {
  activity_based: 'Activity-based',
  spend_proxy: 'Spend proxy (estimate)',
  'spend-proxy': 'Spend proxy (estimate)',
  tier_2_spend: 'Spend proxy (estimate)',
  estimate: 'Estimate',
  excluded: 'Excluded',
  ocr_consumption_activity: 'Bill quantity (activity-based)',
};

const TIER_LABELS: Record<string, string> = {
  tier_1_activity: 'Tier 1 — measured activity',
  tier_2_spend_proxy: 'Tier 2 — spend estimate',
  tier_3_estimate: 'Tier 3 — estimate',
  excluded: 'Excluded from inventory',
};

const humanize = (value: unknown): string =>
  String(value ?? '')
    .replace(/_/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const finite = (value: unknown): number | null => {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

const kgText = (value: unknown): string | null => {
  const number = finite(value);
  if (number == null) return null;
  return `${number.toLocaleString('en-IN', { maximumFractionDigits: 4 })} kg CO₂e`;
};

const plainNumber = (value: unknown, digits = 4): string | null => {
  const number = finite(value);
  if (number == null) return null;
  return number.toLocaleString('en-IN', { maximumFractionDigits: digits });
};

const pushRow = (rows: CalculationFactorRow[], label: string, value: unknown) => {
  if (value == null) return;
  const text = String(value).trim();
  if (!text || text === 'null' || text === 'undefined') return;
  rows.push({ label, value: text });
};

const flagList = (flags: CalculationFootprintInput['complianceFlags']): string[] => {
  if (Array.isArray(flags)) {
    return flags.map((flag) => humanize(flag)).filter(Boolean);
  }
  if (flags && typeof flags === 'object') {
    return Object.entries(flags)
      .filter(([, on]) => Boolean(on))
      .map(([flag]) => humanize(flag));
  }
  return [];
};

const scopeSentence = (breakdown?: { scope1?: number; scope2?: number; scope3?: number }): string | null => {
  if (!breakdown) return null;
  const parts = [
    ['Scope 1', breakdown.scope1],
    ['Scope 2', breakdown.scope2],
    ['Scope 3', breakdown.scope3],
  ]
    .map(([label, value]) => {
      const text = kgText(value);
      return text ? `${label} ${text}` : null;
    })
    .filter(Boolean);
  return parts.length ? parts.join(' · ') : null;
};

export function buildTransactionCalculationReadout(
  footprint: CalculationFootprintInput | null | undefined,
  context: CalculationContextInput = {}
): TransactionCalculationReadout {
  const fp = footprint || {};
  const lineage = fp.factorLineage || {};
  const fuel = (fp.fuelContext || fp.metrics?.fuelContext || {}) as Record<string, unknown>;
  const fera = fp.feraSupplement || fp.screeningFeraSupplement || null;
  const td = fp.tdLossSupplement || fp.screeningTdLossSupplement || null;
  const methodKey = String(fp.quantificationMethod || fp.calculationMethod || '').toLowerCase();
  const methodLabel = METHOD_LABELS[methodKey] || humanize(methodKey) || 'Not recorded';
  const tierLabel = TIER_LABELS[String(fp.dataQualityTier || '')] || humanize(fp.dataQualityTier) || 'Not recorded';

  const inventoryKg = finite(fp.co2Emissions);
  const screeningKg = finite(fp.screeningCo2Emissions);
  const shownKg = inventoryKg && inventoryKg > 0 ? inventoryKg : screeningKg;
  const headline = shownKg == null
    ? '0 kg CO₂e'
    : `${shownKg.toLocaleString('en-IN', { maximumFractionDigits: 2 })} kg CO₂e`;

  const quantity = finite(fp.activityQuantity) ?? finite(context.quantity) ?? finite(fuel.estimatedConsumption);
  const unit = fp.activityUnit || context.unit || (fuel.physicalUnit ? String(fuel.physicalUnit) : '');
  const factor = finite(lineage.factor) ?? finite(fuel.fuelEmissionFactor);
  const factorUnit = lineage.unit || (fuel.fuelEmissionFactorUnit ? String(fuel.fuelEmissionFactorUnit) : '');

  const steps: string[] = [];
  if (fp.exclusionReason) {
    steps.push(`This row is excluded from the inventory (${humanize(fp.exclusionReason)}).`);
  }
  if (quantity != null && quantity > 0 && factor != null) {
    const product = quantity * factor;
    steps.push(
      `${plainNumber(quantity, 4)} ${unit || 'units'} × ${plainNumber(factor, 6)} ${factorUnit} = ${kgText(product)}.`
    );
  } else if (finite(context.amount) != null && finite(fuel.fuelPricePerLiter) != null && factor != null) {
    const price = finite(fuel.fuelPricePerLiter) as number;
    const estimated = (finite(context.amount) as number) / price;
    steps.push(
      `₹${plainNumber(context.amount, 2)} ÷ ${plainNumber(price, 2)} ${fuel.fuelPriceUnit || 'per unit'} = ${plainNumber(estimated, 4)} ${unit || 'units'}.`
    );
    steps.push(
      `${plainNumber(estimated, 4)} ${unit || 'units'} × ${plainNumber(factor, 6)} ${factorUnit} = ${kgText(estimated * factor)}.`
    );
  }
  if (fera && finite(fera.wttFactor) != null && finite(fera.feraKg) != null) {
    steps.push(
      `Fuel well-to-tank factor ${plainNumber(fera.wttFactor, 4)} ${fera.wttUnit || ''} adds ${kgText(fera.feraKg)} (Scope 3, fuel- and energy-related).`
    );
  } else if (fera && finite(fera.feraKg) != null && (finite(fera.feraKg) as number) > 0) {
    steps.push(`Upstream supplement adds ${kgText(fera.feraKg)}.`);
  }
  if (td && finite(td.tdLossKg) != null && (finite(td.tdLossKg) as number) > 0) {
    const rate = finite(td.lossRate);
    const rateText = rate != null ? `${plainNumber(rate * 100, 2)}% × direct emissions` : 'the CEA loss percent × direct emissions';
    steps.push(
      `Transmission and distribution loss is ${rateText}, which adds ${kgText(td.tdLossKg)}. The loss percent is multiplied directly.`
    );
  }
  const scopeLine = scopeSentence(
    (inventoryKg && inventoryKg > 0 ? fp.emissionBreakdown : fp.screeningEmissionBreakdown) || fp.emissionBreakdown
  );
  if (scopeLine) {
    steps.push(`Split across scopes: ${scopeLine}.`);
  }
  if ((inventoryKg == null || inventoryKg === 0) && screeningKg != null && screeningKg > 0) {
    steps.push(
      `The ${kgText(screeningKg)} figure is a screening estimate. Compliance inventory keeps this spend-proxy row at zero until an activity quantity is entered.`
    );
  }
  if (steps.length === 0) {
    steps.push('No activity quantity or emission factor was stored on this transaction.');
  }

  const summary = steps.slice(0, 2).join(' ');

  const resultRows: CalculationFactorRow[] = [];
  pushRow(resultRows, 'Inventory result', inventoryKg != null ? kgText(inventoryKg) : null);
  pushRow(resultRows, 'Screening estimate', screeningKg != null && screeningKg > 0 ? kgText(screeningKg) : null);
  pushRow(resultRows, 'Scope split', scopeSentence(fp.emissionBreakdown));
  pushRow(resultRows, 'Screening scope split', scopeSentence(fp.screeningEmissionBreakdown));
  pushRow(resultRows, 'Method', methodLabel);
  pushRow(resultRows, 'Data quality', tierLabel);
  pushRow(resultRows, 'Reporting mode', humanize(fp.reportingMode));
  pushRow(resultRows, 'Scope 3 category', humanize(fp.ghgScope3Category));
  pushRow(resultRows, 'Estimated scope', humanize(fp.metrics?.estimatedScope));
  pushRow(resultRows, 'kg CO₂e per ₹1,000', plainNumber(fp.metrics?.emissionsPerThousandCurrency, 4));
  pushRow(resultRows, 'Biogenic CO₂ (separate)', kgText(fp.biogenicCo2Kg));

  const activityRows: CalculationFactorRow[] = [];
  pushRow(activityRows, 'Description', context.description);
  pushRow(activityRows, 'Category', humanize(context.category));
  pushRow(activityRows, 'Sub-category', humanize(context.subcategory));
  pushRow(activityRows, 'Amount', finite(context.amount) != null ? `₹${plainNumber(context.amount, 2)}` : null);
  pushRow(activityRows, 'Activity quantity', quantity != null ? `${plainNumber(quantity, 4)} ${unit}`.trim() : null);
  pushRow(activityRows, 'Consumption method', humanize(fuel.consumptionMethod));
  pushRow(activityRows, 'Ownership', humanize(context.ownership));
  if (fp.taxableAmountMeta?.gstStripped) {
    pushRow(activityRows, 'Amount used after GST', plainNumber(fp.taxableAmountMeta.amount, 2));
  }

  const factorRows: CalculationFactorRow[] = [];
  pushRow(factorRows, 'Factor name', lineage.id ? humanize(lineage.id) : null);
  pushRow(factorRows, 'Factor id', lineage.id);
  if (factor != null) {
    pushRow(factorRows, 'Emission factor', `${plainNumber(factor, 6)} ${factorUnit}`.trim());
  }
  pushRow(factorRows, 'Fuel type', humanize(fuel.fuelType));
  pushRow(factorRows, 'Fuel emission factor', finite(fuel.fuelEmissionFactor) != null
    ? `${plainNumber(fuel.fuelEmissionFactor, 6)} ${fuel.fuelEmissionFactorUnit || ''}`.trim()
    : null);
  pushRow(factorRows, 'Well-to-tank factor', fera && finite(fera.wttFactor) != null
    ? `${plainNumber(fera.wttFactor, 6)} ${fera.wttUnit || ''}`.trim()
    : null);
  pushRow(factorRows, 'Well-to-tank method', humanize(fera?.upstreamMethod));
  pushRow(factorRows, 'Well-to-tank result', kgText(fera?.feraKg));
  if (td && finite(td.lossRate) != null) {
    pushRow(factorRows, 'T&D loss rate', `${plainNumber((finite(td.lossRate) as number) * 100, 2)}%`);
  }
  pushRow(factorRows, 'T&D application', humanize(td?.application || td?.upstreamMethod));
  pushRow(factorRows, 'T&D result', kgText(td?.tdLossKg));
  pushRow(factorRows, 'T&D rationale', td?.rationale);
  const applied = fp.metrics?.appliedFactors || {};
  Object.entries(applied).forEach(([key, value]) => {
    if (finite(value) == null && (value == null || value === '')) return;
    pushRow(factorRows, humanize(key), finite(value) != null ? plainNumber(value, 6) : String(value));
  });

  const priceRows: CalculationFactorRow[] = [];
  pushRow(priceRows, 'Fuel price', finite(fuel.fuelPricePerLiter) != null
    ? `${plainNumber(fuel.fuelPricePerLiter, 2)} ${fuel.fuelPriceUnit || ''}`.trim()
    : null);
  pushRow(priceRows, 'Price source', humanize(fuel.source || fuel.priceBasis));
  pushRow(priceRows, 'Price authority', fuel.authority);
  pushRow(priceRows, 'Price location', fuel.location);
  pushRow(priceRows, 'Price date', fuel.priceDate || fuel.lastUpdated);
  pushRow(priceRows, 'Price basis', humanize(fuel.priceBasis));

  const sourceRows: CalculationFactorRow[] = [];
  pushRow(sourceRows, 'Publisher / source', lineage.source);
  pushRow(sourceRows, 'Source version', lineage.sourceVersion);
  pushRow(sourceRows, 'Source document', lineage.sourceDocument);
  pushRow(sourceRows, 'Source URL', lineage.sourceUrl);
  pushRow(sourceRows, 'Geography', lineage.geography);
  pushRow(sourceRows, 'GWP basis', lineage.gwpBasis);
  if (finite(lineage.relativeUncertainty) != null) {
    pushRow(sourceRows, 'Relative uncertainty', `±${plainNumber((finite(lineage.relativeUncertainty) as number) * 100, 1)}%`);
  }
  pushRow(sourceRows, 'Justification', lineage.justification || lineage.notes);
  pushRow(sourceRows, 'Biogenic reporting', lineage.biogenic ? 'Reported separately from fossil CO₂e' : null);
  pushRow(sourceRows, 'Model version', fp.carbonModelVersion);
  pushRow(sourceRows, 'Reporting label', humanize(fp.carbonReportingLabel));

  const scope2 = fp.scope2Reporting;
  const scope2Rows: CalculationFactorRow[] = [];
  pushRow(scope2Rows, 'Location-based', kgText(scope2?.locationBasedKg));
  pushRow(scope2Rows, 'Market-based', kgText(scope2?.marketBasedKg));
  pushRow(scope2Rows, 'Scope 2 method', humanize(scope2?.method));

  const noteRows: CalculationFactorRow[] = [];
  pushRow(noteRows, 'Exclusion', humanize(fp.exclusionReason));
  const flags = flagList(fp.complianceFlags);
  if (flags.length) {
    pushRow(noteRows, 'Calculation notes', flags.join('; '));
  }

  const groups = [
    { title: 'Result', rows: resultRows },
    { title: 'Activity', rows: activityRows },
    { title: 'Emission factors', rows: factorRows },
    { title: 'Prices used', rows: priceRows },
    { title: 'Source and uncertainty', rows: sourceRows },
    { title: 'Scope 2 reporting', rows: scope2Rows },
    { title: 'Notes', rows: noteRows },
  ].filter((group) => group.rows.length > 0);

  return {
    headline: screeningKg != null && screeningKg > 0 && (inventoryKg == null || inventoryKg === 0)
      ? `${headline} screening`
      : headline,
    methodLabel,
    tierLabel,
    summary,
    steps,
    groups,
  };
}
